"""`@zuke/tally` 0.1.0: Tasks of the other shapes the Python facade generator must read: an object literal rather than an interface, positional JSON arguments with JSON results, an optional argument, a task named by a Python keyword, settings that run no command, and a setter that answers nothing.

Generated by ``zuke pythonFacades`` from the wrapper's own documentation; edit
the wrapper in zuke-build/zuke, not this file.
"""

from __future__ import annotations

from collections.abc import Callable, Sequence
from typing import Self

from zuke import Context
from zuke._facade import Settings, call, configured

PACKAGE = "tally"
VERSION = "0.1.0"


class Tuning(Settings):
    """Settings of a task that runs no command: a plain object with setters."""

    def level(
        self,
        n: float,
    ) -> Self:
        """Set the level."""
        return self._record("level", n)

    def reset(self) -> None:
        """Back to zero; answers nothing, as a setter written as a statement might."""
        self._record("reset")


class TallyTasks:
    """Plain functions of several shapes."""

    @staticmethod
    async def add(
        ctx: Context,
        a: float,
        b: float,
    ) -> object:
        """Add two numbers."""
        return await call(
            ctx,
            PACKAGE,
            VERSION,
            "TallyTasks",
            "add",
            [a, b],
        )

    @staticmethod
    async def pass_(ctx: Context) -> None:
        """Do nothing, under a name Python reserves."""
        await call(
            ctx,
            PACKAGE,
            VERSION,
            "TallyTasks",
            "pass",
            [],
        )

    @staticmethod
    async def count(
        ctx: Context,
        items: Sequence[str],
        skip: str | None = None,
    ) -> object:
        """Count the items, leaving out the one to skip."""
        return await call(
            ctx,
            PACKAGE,
            VERSION,
            "TallyTasks",
            "count",
            [items, skip],
        )

    @staticmethod
    async def tune(
        ctx: Context,
        configure: Callable[[Tuning], Tuning],
    ) -> object:
        """Tune, through settings that run nothing."""
        return await call(
            ctx,
            PACKAGE,
            VERSION,
            "TallyTasks",
            "tune",
            [configured(Tuning(), configure)],
        )
